import osimport secretsfrom openai import OpenAIfrom mcp.server import MCPServerfrom mcp.server.transport_security import TransportSecuritySettingsfrom starlette.responses import PlainTextResponse# Read secrets from environmentOPENAI_API_KEY = os.getenv("OPENAI_API_KEY")MCP_SECRET = os.getenv("MCP_SECRET")OPENAI_MODEL = os.getenv("OPENAI_MODEL", "gpt-5.5")if not OPENAI_API_KEY:    raise RuntimeError("OPENAI_API_KEY is missing")if not MCP_SECRET or len(MCP_SECRET) < 32:    raise RuntimeError("MCP_SECRET must be at least 32 characters")# OpenAI clientclient = OpenAI(api_key=OPENAI_API_KEY)# MCP servermcp = MCPServer("ChatGPT Bridge")@mcp.tool()def ask_gpt(prompt: str) -> str:    """Ask OpenAI GPT a question or request coding help."""    response = client.responses.create(        model=OPENAI_MODEL,        input=prompt,    )    return response.output_text# Allowed server hostnamesallowed_hosts = [    "localhost",    "localhost:*",    "127.0.0.1",    "127.0.0.1:*",]allowed_origins = [    "http://localhost:8000",    "http://127.0.0.1:8000",]public_host = os.getenv("MCP_PUBLIC_HOST", "").strip()if public_host:    allowed_hosts.extend([        public_host,        f"{public_host}:*",    ])    allowed_origins.append(f"https://{public_host}")security = TransportSecuritySettings(    allowed_hosts=allowed_hosts,    allowed_origins=allowed_origins,)# Protect MCP with a secret request headerclass SecretMiddleware:    def __init__(self, app):        self.app = app    async def __call__(self, scope, receive, send):        if (            scope["type"] == "http"            and scope.get("path", "").startswith("/mcp")        ):            headers = dict(scope.get("headers", []))            received = headers.get(b"x-mcp-secret", b"")            if not secrets.compare_digest(                received, MCP_SECRET.encode("utf-8")            ):                response = PlainTextResponse(                    "Unauthorized",                    status_code=401,                )                await response(scope, receive, send)                return        await self.app(scope, receive, send)# ASGI applicationapp = SecretMiddleware(    mcp.streamable_http_app(        stateless_http=True,        json_response=True,        transport_security=security,    ))